import React, { useEffect, useRef, useState } from "react";
import _ from 'lodash';
import { IfrmaeAppProps } from "@/types/iframe";
import DevelopSetting, { settingStore } from './components/DevelopSetting';
import { useObserver } from "mobx-react-lite";
import { Button, Result } from "@arco-design/web-react";
import { MobileKey } from "@/types/mobile";

const win: IfrmaeAppProps = window as any;
const { pageStore } = win;
export default () => {
    
    const [store] = useState(() => new settingStore())

    useEffect(() => {

        const handleMessage = (event) => {
            if(typeof event.data == "object"){
                const { key } = event.data;
                switch(key){
                    case MobileKey.IframeAppReady:
                        // 更新状态
                        store.setIsFrameReady(true);
                    break;
                }
            }
        };
    
        window.addEventListener('message', handleMessage);
    
        return () => {
            window.removeEventListener('message', handleMessage);
        };
    }, []);

    return useObserver(() => {

        useEffect(() => {
            const iframe = store.iframeRef.current;
            if(iframe){
                Object.assign(
                    iframe.contentWindow,
                    {
                        iframeApp: true,
                        ..._.pick(win, ['moduleStore', 'fileStore', 'app', 'language', 'pageStore'])
                    } as IfrmaeAppProps
                )
            }
        },[store.isReady])

        if(!pageStore){
            return (
                <Result
                    status='error'
                    title='错误提示'
                    subTitle='请从编译器中打开当前页面'
                    extra={[
                        <Button key='again' style={{ margin: '0 16px' }}
                            onClick={() => {
                                window.close();
                            }}
                        >
                            关闭
                        </Button>
                    ]}
                ></Result>
            )
        }
    
      
            
        return (
            <div className="h-full w-full flex flex-col f">
                {store.isFrameReady? (
                    <DevelopSetting store={store} key={store.key}/>
                ): null}
                {store.isReady? (
                    <iframe
                        ref={store.iframeRef}
                        src={`${location.origin}/`}
                        className="grow"
                        // onLoad={() => {
                        //     store.setIsFrameReady(true);
                        // }}
                    >
                    </iframe>
                ): null}
            </div>
        )
    })
}